// Build the same server as one file for Cloudflare's browser code editor.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const output = mkdtempSync(join(tmpdir(), "basho-dashboard-"));
try {
  execFileSync("npx", ["--yes", "wrangler@4.151.0", "deploy", "--dry-run", "--outdir", output], { cwd: root, stdio: "inherit" });
  const source = readFileSync(join(output, "worker.js"), "utf8").replace(/^\/\/# sourceMappingURL=.*$/gm, "").trim();
  writeFileSync(join(root, "dashboard-worker.js"), "// Generated by node ai-service/build-dashboard.mjs. Paste the entire file into Cloudflare worker.js.\n" + source + "\n");
} finally { rmSync(output, { recursive: true, force: true }); }
